def min_product(tuples):
    tuples = sorted(tuples, key=lambda x: x[0])
    min_product = tuples[0][0]
    for i in range(1, len(tuples)):
        product = tuples[i][0] * tuples[i - 1][1]
        if product < min_product:
            min_product = product
    return min_product

