def roman_to_int(roman):
    """
    Converts a roman numeral to an integer.
    """
    roman_dict = {
        'I': 1,
        'V': 5,
        'X': 10,
        'L': 50,
        'C': 100,
        'D': 500,
        'M': 1000
    }
    roman_numeral = ''
    for char in roman:
        if char in roman_dict:
            roman_numeral += roman_dict[char]
        else:
            roman_numeral += char
    return int(roman_numeral)

