def most_common_char(s):
    char_count = {}
    max_count = 0

    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

        if char_count[char] > max_count:
            max_count = char_count[char]

    return max_count, list(char_count.keys())[0]

from itertools import groupby
def modified_encode(alist):
        def ctr_ele(el):
            if len(el)>1: return [len(el), el[0]]
            else: return el[0]
        return [ctr_ele(list(group)) for key, group in groupby(alist)]

def count_most_common_char(s):
    """
    Count the most common character in a given string.
    """
    counts = {}
    for c in s:
        counts[c] = counts.get(c, 0) + 1
    return max(counts, key=counts.get)

def count_until_tuple(lst):
    count = 0
    for item in lst:
        if isinstance(item, tuple):
            return count
        count += 1
    return count

def hexagon_grid(size):
    grid = []
    for i in range(size):
        row = []
        for j in range(6):
            x = i * 2 + j % 2 * 2 - 1
            y = i * 3 - j // 2 * 3
            row.append((x, y))
        grid.append(row)
    return grid
